TorLauncherAsyncWaiter::TorLauncherAsyncWaiter(
    TorLauncher* proxy) : proxy_(proxy) {}

TorLauncherAsyncWaiter::~TorLauncherAsyncWaiter() = default;


void TorLauncherAsyncWaiter::Launch(
    TorConfigPtr config, bool* out_result, int64_t* out_pid) {
  base::RunLoop loop;
  proxy_->Launch(
      std::move(config),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_result
,
             int64_t* out_pid
,
             bool result,
             int64_t pid) {*out_result = std::move(result);*out_pid = std::move(pid);
            loop->Quit();
          },
          &loop,
          out_result,
          out_pid));
  loop.Run();
}



void TorLauncherAsyncWaiter::SetCrashHandler(
    int64_t* out_pid) {
  base::RunLoop loop;
  proxy_->SetCrashHandler(
      base::BindOnce(
          [](base::RunLoop* loop,
             int64_t* out_pid
,
             int64_t pid) {*out_pid = std::move(pid);
            loop->Quit();
          },
          &loop,
          out_pid));
  loop.Run();
}

int64_t TorLauncherAsyncWaiter::SetCrashHandler(
    ) {
  int64_t async_wait_result;
  SetCrashHandler(&async_wait_result);
  return async_wait_result;
}






